<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessageBox,ElMessage} from 'element-plus'
import {api,post,formatDate} from '../api'
import {states} from '../project'
import type {Project,RequestRow} from '../project'
import type {Evaluation} from '../types'
import WorkflowProgress from '../components/WorkflowProgress.vue'
import EvaluationReport from '../components/EvaluationReport.vue'
import V19Report from '../components/V19Report.vue'
const route=useRoute(),router=useRouter(),projects=ref<Project[]>([]),requests=ref<RequestRow[]>([]),projectId=ref(''),status=ref('all'),detail=ref<any>(null),step=ref(0),error=ref(''),busy=ref(false),scope=ref(''),refreshMaterials=ref(false),wu=ref<Evaluation|null>(null),reportTab=ref('dual')
const visible=computed(()=>requests.value.filter(r=>(!projectId.value||r.project_id===projectId.value)&&(status.value==='all'||(status.value==='pending_acceptance'?r.status==='pending_acceptance':status.value==='attention'?['waiting','failed'].includes(r.status):status.value==='active'?['queued','running','processing'].includes(r.status):['succeeded','awaiting_acceptance','accepted'].includes(r.status)))))
const scopeRequired=computed(()=>Object.values(detail.value?.workflow?.waiting||{}).some((w:any)=>w.details?.status==='needs_scope_confirmation'||w.details?.evaluation_status==='needs_scope_confirmation'))
const stageKeys=[['wu_intake'],['search_replay'],['attribution'],['wu_evaluation','v19_evaluation','export']]
const outputs=computed(()=>detail.value?.outputs||{}),intake=computed(()=>outputs.value.wu_intake?.intake),search=computed(()=>outputs.value.search_replay),attribution=computed(()=>outputs.value.attribution)
const files=computed(()=>(detail.value?.workflow?.files||[]).filter((f:any)=>stageKeys[step.value]!.some(k=>f.path.startsWith(k+'/'))))
const cardNames:Record<string,string>={outcome_name:'成果名称',outcome_type:'成果类型',description:'成果概述',problem_solved:'解决的问题',participating_units:'参与单位',core_members:'核心成员',related_outputs:'关联产出',key_metrics:'关键指标',baseline:'对照基线',ai_role:'AI 作用',claimed_application:'应用情况',support_materials:'支撑材料'}
const moduleNames:Record<string,string>={sota:'技术水平对照',prior_work:'前期工作核验',usage_media:'应用与传播',github:'开源与复用',indicator:'指标核验'}
let timer:ReturnType<typeof setInterval>|undefined
async function load(){try{[projects.value,requests.value]=await Promise.all([api<Project[]>('/admin/projects'),api<RequestRow[]>('/admin/requests')]);if(detail.value){const id=detail.value.id;const updated=await api<any>('/admin/requests/'+id);if(detail.value?.id===id)detail.value=updated}error.value=''}catch(e){error.value=(e as Error).message}}
async function inspect(r:RequestRow){busy.value=true;error.value='';wu.value=null;scope.value='';refreshMaterials.value=false;try{detail.value=await api('/admin/requests/'+r.id);step.value=Math.max(0,r.steps.findIndex(s=>s.status!=='succeeded'));await router.replace({path:'/admin',query:{tab:'requests',ticket:r.id}});if(detail.value.outputs?.wu_evaluation){const report=await api<{payload:Evaluation}>('/admin/pipeline-reports/'+r.pipeline_id);wu.value=report.payload}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function back(){detail.value=null;await router.replace({path:'/admin',query:{tab:'requests'}});await load()}
async function resume(){busy.value=true;error.value='';try{await post('/admin/requests/'+detail.value.id+'/continue',{revision:detail.value.revision,confirmed_scope:scope.value,refresh_materials:refreshMaterials.value});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function receive(r:RequestRow){busy.value=true;error.value='';try{await post('/admin/requests/'+r.id+'/receive',{revision:r.revision});await load();ElMessage.success('已受理并加入执行队列')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(r:RequestRow){
 try{await ElMessageBox.confirm(`删除“${r.outcome_name}”的工单、工作流、过程文件及报告？用户端对应记录也会移除。`,'删除工作流',{confirmButtonText:'删除工作流',cancelButtonText:'取消',type:'warning'})}catch{return}
 busy.value=true;error.value='';try{await api('/admin/requests/'+r.id,{method:'DELETE'});if(detail.value?.id===r.id)await back();else await load();ElMessage.success('工作流已删除')}catch(e){error.value=(e as Error).message}finally{busy.value=false}
}
function download(path:string){return '/api/admin/pipelines/'+detail.value.pipeline_id+'/artifact?path='+encodeURIComponent(path)}
function sourceText(e:any){try{const parsed=JSON.parse(e.text);return parsed.quote||parsed.title||e.text}catch{return e.text}}
onMounted(async()=>{await load();const target=requests.value.find(r=>r.id===route.query.ticket||r.pipeline_id===route.query.pipeline);if(target)await inspect(target);timer=setInterval(()=>{if(!busy.value)load()},5000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="content-page project-page"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="!detail"><div class="project-toolbar"><el-select v-model="projectId" clearable placeholder="全部项目" aria-label="筛选工单项目" class="project-select"><el-option v-for="p in projects" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-button @click="load">刷新</el-button></div><div class="section-heading"><h2>工单与工作流</h2><el-radio-group v-model="status"><el-radio-button value="all">全部</el-radio-button><el-radio-button value="pending_acceptance">待受理</el-radio-button><el-radio-button value="active">处理中</el-radio-button><el-radio-button value="attention">待处理异常</el-radio-button><el-radio-button value="done">已完成</el-radio-button></el-radio-group></div><article v-for="r in visible" :key="r.id" class="panel request-card"><div class="request-card-heading"><div><button class="request-title" @click="inspect(r)">{{r.outcome_name}}</button><p class="request-project">{{r.project_name}} · {{formatDate(r.created_at)}}</p></div><span class="status-pill" :class="r.status">{{states[r.status]||r.status}}</span></div><WorkflowProgress :steps="r.steps"/><div class="request-card-footer"><p v-if="r.status==='failed'||r.status==='waiting'">{{r.note}}</p><el-button v-if="r.status==='pending_acceptance'" type="primary" :disabled="busy" @click="receive(r)">受理并启动</el-button><el-button type="primary" plain @click="inspect(r)">查看工作流</el-button><el-button type="danger" text :disabled="busy||r.status==='running'" @click="remove(r)">删除工作流</el-button></div></article><div v-if="!visible.length" class="panel empty-project">暂无符合条件的工单</div></template><template v-else><div class="project-toolbar"><div><el-button text @click="back">← 工单列表</el-button><h2 class="project-heading">{{detail.outcome_name}}</h2><p class="request-project">{{detail.project_name}}</p></div><div class="toolbar-actions"><span class="status-pill" :class="detail.status">{{states[detail.status]}}</span><el-button v-if="detail.status==='pending_acceptance'" type="primary" :disabled="busy" @click="receive(detail)">受理并启动</el-button><el-button type="danger" plain :disabled="busy||detail.status==='running'" @click="remove(detail)">删除工作流</el-button></div></div><p v-if="detail.received_at" class="request-project">受理于 {{formatDate(detail.received_at)}}<span v-if="detail.accepted_at"> · 用户验收于 {{formatDate(detail.accepted_at)}}</span></p><WorkflowProgress :steps="detail.steps" :selected="step" interactive @select="step=$event"/><section v-if="['waiting','failed'].includes(detail.status)" class="panel resolve-panel"><h3>{{detail.status==='waiting'?'补充后继续处理':'处理异常'}}</h3><p>{{detail.error||detail.note}}</p><el-form label-position="top" @submit.prevent="resume"><el-form-item v-if="scopeRequired" label="确认存在歧义的成果范围"><el-input v-model="scope" maxlength="200"/></el-form-item><el-checkbox v-model="refreshMaterials">重新读取该项目选用的原始材料</el-checkbox><div class="dialog-actions"><RouterLink :to="{path:'/admin',query:{tab:'projects'}}" class="text-link">管理项目材料与日期</RouterLink><el-button type="primary" native-type="submit" :loading="busy">继续工作流</el-button></div></el-form></section><section class="stage-content"><template v-if="step===0&&intake"><div class="panel padded"><h2>成果卡</h2><dl class="outcome-fields"><div v-for="field in intake.outcome_card" :key="field.name"><dt>{{cardNames[field.name]||field.name}}</dt><dd>{{field.value||'待补充'}}</dd></div></dl></div><el-collapse class="panel padded"><el-collapse-item title="原文依据" name="evidence"><div v-for="e in intake.evidence" :key="e.id" class="evidence-block"><strong>{{e.locator}}</strong><blockquote>{{e.quote}}</blockquote></div></el-collapse-item></el-collapse></template><template v-else-if="step===1&&search"><div class="panel padded"><h2>外部 Search</h2><p v-if="search.raw_result?.review_cutoff">核验截至 {{search.raw_result.review_cutoff}}</p><div v-for="m in search.raw_result?.modules||[]" :key="m.id" class="finding-row"><h3>{{moduleNames[m.id]||m.id}}</h3><p>{{m.summary}}</p><ul v-if="m.limitations?.length"><li v-for="item in m.limitations" :key="item">{{item}}</li></ul></div><div v-for="f in search.replay?.findings||[]" :key="f.id" class="finding-row"><h3>{{f.statement}}</h3><p>{{f.reason}}</p></div><el-collapse><el-collapse-item title="检索依据" name="sources"><div v-for="e in search.replay?.evidence||[]" :key="e.id" class="finding-row"><a v-if="/^https?:\/\//.test(e.url||'')" :href="e.url" target="_blank" rel="noopener noreferrer">{{e.locator}}</a><p>{{sourceText(e)}}</p></div></el-collapse-item></el-collapse></div></template><template v-else-if="step===2&&attribution"><div class="panel padded"><h2>贡献归因</h2><p class="stage-summary">{{attribution.contribution_result?.summary}}</p><div v-for="f in attribution.contribution_result?.factor_results||[]" :key="f.factor_id" class="finding-row"><h3>{{f.factor_name}}</h3><p>{{f.role}}</p><p>{{f.conclusion}}</p></div><el-collapse><el-collapse-item title="未解决事项" name="gaps"><div v-for="u in attribution.unresolved_items?.items||[]" :key="u.id" class="finding-row"><h3>{{u.unresolved_question||u.object}}</h3><p>{{u.reason}}</p></div></el-collapse-item></el-collapse></div></template><template v-else-if="step===3&&(outputs.v19_evaluation||outputs.wu_evaluation)"><el-tabs v-model="reportTab"><el-tab-pane label="双层影响力评价" name="dual"><V19Report v-if="outputs.v19_evaluation" :value="outputs.v19_evaluation.result"/><div v-else class="panel empty-project">双层影响力评价尚未完成</div></el-tab-pane><el-tab-pane label="成果评价依据" name="wu"><EvaluationReport v-if="wu" :value="wu"/><el-button v-else @click="inspect(detail)">读取成果评价</el-button></el-tab-pane></el-tabs><RouterLink v-if="detail.result_id" :to="'/results/'+detail.result_id" class="primary-link">打开用户端报告 ↗</RouterLink></template><div v-else class="panel empty-project">{{detail.steps[step]?.name}} · {{states[detail.steps[step]?.status]||'未开始'}}</div></section><el-collapse v-if="files.length" class="panel padded stage-files"><el-collapse-item title="本阶段过程文件" name="files"><div v-for="f in files" :key="f.path" class="artifact-row"><span>{{f.path.split('/').slice(2).join('/')}}</span><a :href="download(f.path)" class="text-link">下载</a></div></el-collapse-item></el-collapse></template></div></template>
